# DbDataProxy's suite: a SQL Server name plus SQL login and a PostgreSQL connection string, each with a switch that makes a missing server a failure instead of a skip.
DBPROXY_TEST_SQLSERVER          <- DBKIT_TEST_MSSQL_SERVER
DBPROXY_TEST_SQLSERVER_USER     <- DBKIT_TEST_MSSQL_USER
DBPROXY_TEST_SQLSERVER_PASSWORD <- DBKIT_TEST_MSSQL_PASSWORD
DBPROXY_REQUIRE_SQLSERVER = true if DBKIT_TEST_MSSQL
DBPROXY_TEST_POSTGRES           <- DBKIT_TEST_POSTGRES
DBPROXY_REQUIRE_POSTGRES = true if DBKIT_TEST_POSTGRES
